insert into public.destinations (name, subtitle, region, elevation, description, story_quote, image, season, tags, featured, coordinates, highlights, sort_order)
values
  ('Darjeeling Tea Belt', 'Biodynamic tea hills, cloud-draped heritage bungalows, and dawn views of Kangchenjunga.', 'Bengal Hills', '2,042m', 'Perched along steep Himalayan ridges, Darjeeling is home to century-old organic tea estates, cool montane forests, and vibrant local farmer cooperatives.', 'The morning mist clears to reveal Kanchenjunga painted in Himalayan amber.', 'https://images.unsplash.com/photo-1544735716-392fe2489ffa?auto=format&fit=crop&w=1200&q=80', 'October to May', array['Organic Tea', 'Kangchenjunga', 'Heritage Trails'], true, '27.0410° N, 88.2663° E', array['Biodynamic Single Estate Teas', 'Tiger Hill Dawn Ridge', 'Ghoom Monastery Pine Belt'], 1),
  ('Kalimpong Orchid Ridge', 'Serene horticultural ridges, Buddhist monasteries, and quiet artisan paper workshops.', 'Bengal Hills', '1,247m', 'A historic Himalayan trade nexus renowned for its exotic orchid nurseries, handmade lokta paper, and quiet Buddhist learning centres.', 'Wind through quiet ridges perfumed with ginger blooms and pine.', 'https://images.unsplash.com/photo-1626621341517-bbf3d9990a23?auto=format&fit=crop&w=1200&q=80', 'Year-round', array['Floriculture', 'Artisan Paper', 'Monastic Groves'], true, '27.0667° N, 88.4667° E', array['Himalayan Orchid Sanctuaries', 'Handmade Lokta Paper Mill', 'Deolo Hill Vista Over Teesta'], 2),
  ('Sikkim Organic Valleys', 'Sacred cedar groves, zero-chemical terraced farms, and high-altitude Buddhist gompas.', 'Sikkim', '1,600m', 'India''s first 100% organic state. Ancient river valleys yield heirloom mountain black cardamom, buckwheat, and medicinal herbs.', 'A living testament to ecological farming in the shadow of sacred peaks.', 'https://images.unsplash.com/photo-1589182373726-e4f658ab50f0?auto=format&fit=crop&w=1200&q=80', 'March to June, Sept to Dec', array['100% Organic', 'Glacial Rivers', 'Sacred Monasteries'], true, '27.5330° N, 88.5122° E', array['Cardamom Farm Cooperatives', 'Pelling Kanchenjunga Vistas', 'Ancient Rumtek Monastery Trail'], 3),
  ('Dooars Foothill Sanctuaries', 'Lush sub-Himalayan floodplains, emerald sal forests, and elephant corridor tea estates.', 'North Bengal', '300m', 'Where the mighty Himalayas meet the Bengal plains. Pristine river corridors, wildlife sanctuaries, and organic riverside homestays.', 'Where wild elephant bells echo against the misty green foothills.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1200&q=80', 'November to April', array['Wildlife Corridors', 'Sal Forests', 'River Sanctuaries'], false, '26.7271° N, 89.0433° E', array['Jaldapara Rhino Grasslands', 'Murti Riverbed Eco-Camps', 'Buxa Tiger Ridge Fort Trek'], 4)
insert into public.homestays (slug, name, region, location, elevation, monthly_rate, security_deposit, min_lease_term, lease_status, furnishing, rating, reviews_count, host_name, host_role, host_years, host_avatar, room_type, wifi, capacity, images, description, amenities, features, utilities_included, is_published)
values
  ('ging-tea-bungalow', 'Ging Heritage Tea Bungalow', 'Bengal Hills', 'Lebong Valley, Darjeeling', '1,920m', '₹28,000/mo', '₹15,000', '1 Month', 'Available for Lease', 'Furnished Teak & Cedar', 4.95, 24, 'Pemba Sherpa', 'Biodynamic Tea Planter', 8, 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=150&q=80', 'Private Sabbatical Wing', 'High-Speed Fiber (250 Mbps)', '1–2 Working Residents', array['https://images.unsplash.com/photo-1542314831-068cd1dbfeeb?auto=format&fit=crop&w=1200&q=85', 'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&w=800&q=80'], 'Overlooking third-generation organic tea terraces in Lebong Valley, this heritage cedar bungalow provides uninterrupted mountain views and dedicated ergonomic workstations.', array['Fiber Broadband (250 Mbps)', 'Hearth Fireplace', 'Daily Organic Farm Breakfast', 'Power Inverter Backup'], array['Ergonomic Teak Desk', 'Solar Geyser', 'Organic Kitchen Garden Access'], array['Electricity & Solar Backup', 'Unlimited Fiber WiFi', 'Spring Water Supply'], true),
  ('orchard-stone-cottage', 'Orchard Ridge Stone Cottage', 'Bengal Hills', 'Relli Valley, Kalimpong', '1,310m', '₹22,000/mo', '₹12,000', '1 Month', 'Available for Lease', 'Handcrafted Pine Furnishing', 4.90, 18, 'Anjali Pradhan', 'Botanical Artisan', 5, 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=150&q=80', 'Entire Stone Cottage', 'Fiber Broadband (150 Mbps)', '2 Residents', array['https://images.unsplash.com/photo-1587061949409-02df41d5e562?auto=format&fit=crop&w=1200&q=85', 'https://images.unsplash.com/photo-1570129477492-45c003edd2be?auto=format&fit=crop&w=800&q=80'], 'Surrounded by citrus orchards and cardamom slopes, this vernacular dry-stone cottage offers total mountain tranquility and fresh local spring water.', array['High-Speed WiFi', 'Orchard Balcony', 'Wood Stove Heating', 'Kitchenette'], array['Cardamom Valley Views', 'Rainwater Harvesting', 'Birdwatching Porch'], array['Filtered Mountain Water', 'High-Speed Broadband', 'Solar Hot Water'], true),
  ('yuksom-cedar-homestead', 'Yuksom Sacred Valley Homestead', 'Sikkim', 'West Sikkim Ridge, Yuksom', '1,780m', '₹25,000/mo', '₹14,000', '1 Month', 'Available for Lease', 'Cedar & Slate Vernacular', 4.98, 31, 'Dawa Bhutia', 'Alpine Conservation Guide', 11, 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=150&q=80', 'Upper Floor Residency', 'Dedicated Fiber (200 Mbps)', '1–3 Residents', array['https://images.unsplash.com/photo-1518780664697-55e3ad937233?auto=format&fit=crop&w=1200&q=85'], 'Positioned at the trailhead of Khangchendzonga National Park, this serene mountain retreat features ancient deodar wood beams and mountain views.', array['Fiber WiFi', 'Mountain Library', 'Himalayan Herbal Hearth', 'Private Balcony'], array['Ancient Deodar Beams', 'Monastery Chime Acoustics', 'Eco Compost System'], array['Wood Heating Allowance', 'Spring Water', 'Fiber Internet'], true),
  ('kurseong-singell-loft', 'Singell Tea Loft & Residency', 'Bengal Hills', 'Singell Tea Belt, Kurseong', '1,458m', '₹24,000/mo', '₹12,000', '1 Month', 'Available for Lease', 'Modern Minimalist Wood', 4.92, 16, 'Karma Lepcha', 'Heritage Tea Sommelier', 6, 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=150&q=80', 'Loft Apartment', 'Dual ISP Fiber (300 Mbps)', '1–2 Residents', array['https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1200&q=85'], 'A quiet writer and developer loft located beside the historic Toy Train pine corridor with misty valley views.', array['Dual ISP WiFi', 'Ergonomic Chair & Desk', 'Espresso Machine', 'Valley View Deck'], array['Toy Train Soundscape', 'Zero Light Pollution', 'Private Tea Tasting'], array['Dual Fiber Connections', 'Power Backup (8 hrs)', 'Water Utilities'], true)
insert into public.mountain_jobs (title, employer, employer_badge, location, region, type, salary, housing_included, category, description, responsibilities, requirements, benefits, is_published, posted_date)
values
  ('Biodynamic Tea Garden Steward', 'Makaibari Agro-Forestry Cooperative', 'Verified Estate Host', 'Kurseong Valley, Bengal', 'Full-time', '₹35,000 – ₹42,000 / mo', true, 'Agriculture & Craft', 'Lead regenerative soil composting and organic tea bush health across 120 hectares of misty sub-Himalayan forest canopy.', array['Manage biodynamic compost prep', 'Coordinate with 80 indigenous plucker families', 'Document seasonal flush yields'], array['3+ years in organic agriculture', 'Knowledge of Himalayan terrain', 'Conversational Nepali or Hindi'], array['Independent stone cottage accommodation', 'Organic hearth meals', 'Annual health fellowship'], true, 'Nov 2, 2026'),
  ('High-Altitude Alpine Guide & Trail Steward', 'Khangchendzonga Conservation Fellowship', 'Ecological Partner', 'Yuksom & Dzongri, Sikkim', 'Seasonal', '₹40,000 – ₹50,000 / season', true, 'Guiding & Conservation', 'Lead low-impact wilderness trail education and enforce the 20kg porter load limit along sacred mountain passes.', array['Accompany trekking fellows', 'Monitor trail litter clean-ups', 'First-aid & wilderness response'], array['IMF or NIM certified mountaineering', 'Fluent English & Hindi', 'Wilderness first responder certification'], array['Basecamp lodge accommodation', 'All high-altitude mountaineering gear provided', 'Nutrition stipend'], true, 'Nov 1, 2026'),
  ('Regenerative Eco-Lodge Manager', 'Teesta Sal Forest Retreat', 'Certified Sanctuary', 'Kalimpong Foothills, Bengal', 'Full-time', '₹38,000 – ₹45,000 / mo', true, 'Hospitality & Estates', 'Oversee day-to-day guest operations, solar microgrid uptime, and organic farm-to-table kitchen logistics.', array['Direct host family coordination', 'Monitor solar inverter battery health', 'Curate respectful guest cultural workshops'], array['Prior boutique hospitality experience', 'Calm demeanour in off-grid settings', 'Basic bookkeeping & digital skills'], array['Private riverside manager cottage', 'Farm pantry produce', 'Quarterly sabbatical week'], true, 'Oct 28, 2026')
insert into public.community_dispatches (type, title, excerpt, full_content, location, date, read_time, author_name, author_role, author_avatar, community_badge, verified, helpful_count, is_published, price_item, price_shared_rate, price_private_rate, price_note, price_last_updated)
values
  ('price_report', 'Siliguri to Darjeeling Shared Taxi & Mountain Route Price Index', 'Verified ground rates for shared Tata Sumos, private Scorpio hires, luggage allowances, and fair driver halting norms along Rohini Road.', 'Verified rates for November 2026 along Rohini Road: Shared Tata Sumo seat: ₹350 per person from Siliguri Junction to Chowrasta Darjeeling. Private Scorpio hire: ₹3,200. Always confirm seat allocation before loading heavy rucksacks.', 'Siliguri Junction ⇄ Darjeeling Town', 'Nov 3, 2026', '3 min read', 'Pemba Tshering', 'Mountain Logistics Steward', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=150&q=80', 'Driver Syndicate Rep', true, 42, true, 'Shared Tata Sumo Seat', '₹350 / seat', '₹3,200 (Private Scorpio)', 'Standard rate along Rohini Road. No festive surge allowed by union.', 'November 2026'),
  ('trail_note', 'Winter Packing & High-Altitude Fiber Broadband Survival Guide', 'Practical tips for remote software engineers and sabbatical writers preparing for a winter month in West Sikkim and Darjeeling ridges.', 'Winter in the Eastern Himalayas brings crystalline blue skies and freezing nights. Ensure you request an oil-radiant heater over coil blowers, carry a 65W GaN powerbank for rolling hilltop outages, and confirm fiber line stability before booking.', 'Yuksom & Kurseong Ridges', 'Oct 29, 2026', '5 min read', 'Sunita Gurung', 'Remote Systems Architect', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=150&q=80', 'Fellowship Alum', true, 38, true, null, null, null, null, null)
